using System.ComponentModel.DataAnnotations;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }

    [MaxLength(20)]
    public string TrackingNumber { get; set; } = string.Empty;

    [MaxLength(200)]
    public string Origin { get; set; } = string.Empty;

    [MaxLength(200)]
    public string Destination { get; set; } = string.Empty;

    public int Status { get; set; }

    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }

    [MaxLength(200)]
    public string RecipientName { get; set; } = string.Empty;

    [MaxLength(200)]
    public string CustomerEmail { get; set; } = string.Empty;
}

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

/// <summary>
/// Used during interactive-server prerendering — talks directly to the DB.
/// </summary>
public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync() =>
        await db.Shipments.AsNoTracking().Select(MapToDto).ToListAsync();

    public async Task<ShipmentDto?> GetByTrackingNumberAsync(string trackingNumber) =>
        await db.Shipments.AsNoTracking()
            .Where(s => s.TrackingNumber == trackingNumber)
            .Select(MapToDto)
            .FirstOrDefaultAsync();

    public async Task<List<ShipmentDto>> GetShipmentsForCustomerAsync(string email) =>
        await db.Shipments.AsNoTracking()
            .Where(s => s.CustomerEmail == email)
            .Select(MapToDto)
            .ToListAsync();

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto dto)
    {
        var entity = new Shipment
        {
            TrackingNumber = GenerateTrackingNumber(),
            Origin = dto.Origin,
            Destination = dto.Destination,
            Status = (int)ShipmentStatus.Pending,
            ShippedDate = DateTime.UtcNow,
            EstimatedDelivery = DateTime.UtcNow.AddDays(5),
            RecipientName = dto.RecipientName,
            CustomerEmail = dto.CustomerEmail,
        };
        db.Shipments.Add(entity);
        await db.SaveChangesAsync();
        return MapToDto.Compile()(entity);
    }

    public async Task UpdateStatusAsync(int id, ShipmentStatus status)
    {
        var entity = await db.Shipments.FindAsync(id)
            ?? throw new KeyNotFoundException($"Shipment {id} not found");
        entity.Status = (int)status;
        if (status == ShipmentStatus.Delivered)
            entity.ActualDelivery = DateTime.UtcNow;
        await db.SaveChangesAsync();
    }

    private static string GenerateTrackingNumber() =>
        $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(100000, 999999)}";

    private static readonly System.Linq.Expressions.Expression<Func<Shipment, ShipmentDto>> MapToDto =
        s => new ShipmentDto
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = (ShipmentStatus)s.Status,
            ShippedDate = s.ShippedDate,
            EstimatedDelivery = s.EstimatedDelivery,
            ActualDelivery = s.ActualDelivery,
            RecipientName = s.RecipientName,
            CustomerEmail = s.CustomerEmail,
        };
}

using Microsoft.AspNetCore.Mvc;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (IShipmentService svc) =>
            Results.Ok(await svc.GetAllShipmentsAsync()))
            .RequireAuthorization("Dispatcher");

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService svc) =>
        {
            var shipment = await svc.GetByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapGet("/customer/{email}", async (string email, IShipmentService svc) =>
            Results.Ok(await svc.GetShipmentsForCustomerAsync(email)));

        group.MapPost("/", async ([FromBody] ShipmentDto dto, IShipmentService svc) =>
        {
            var created = await svc.CreateShipmentAsync(dto);
            return Results.Created($"api/shipments/track/{created.TrackingNumber}", created);
        }).RequireAuthorization("Dispatcher");

        group.MapPut("/{id:int}/status", async (int id, [FromBody] UpdateShipmentStatusRequest req, IShipmentService svc) =>
        {
            await svc.UpdateStatusAsync(id, req.NewStatus);
            return Results.NoContent();
        }).RequireAuthorization("Dispatcher");
    }
}

