using Microsoft.AspNetCore.Mvc;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (IShipmentService svc) =>
            Results.Ok(await svc.GetAllShipmentsAsync()))
            .RequireAuthorization("Dispatcher");

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService svc) =>
        {
            var shipment = await svc.GetByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapGet("/customer/{email}", async (string email, IShipmentService svc) =>
            Results.Ok(await svc.GetShipmentsForCustomerAsync(email)));

        group.MapPost("/", async ([FromBody] ShipmentDto dto, IShipmentService svc) =>
        {
            var created = await svc.CreateShipmentAsync(dto);
            return Results.Created($"api/shipments/track/{created.TrackingNumber}", created);
        }).RequireAuthorization("Dispatcher");

        group.MapPut("/{id:int}/status", async (int id, [FromBody] UpdateShipmentStatusRequest req, IShipmentService svc) =>
        {
            await svc.UpdateStatusAsync(id, req.NewStatus);
            return Results.NoContent();
        }).RequireAuthorization("Dispatcher");
    }
}

