@page "/shipments"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize(Roles = "Dispatcher")]
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Shipment Dashboard</PageTitle>

<h2>📦 Shipment Dashboard</h2>

<div class="mb-3 d-flex gap-2 flex-wrap align-items-end">
    <div>
        <label class="form-label mb-1">Filter by Status</label>
        <select class="form-select" @bind="statusFilter">
            <option value="">All</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
    <div>
        <label class="form-label mb-1">Search</label>
        <input type="text" class="form-control" placeholder="Tracking # or destination…"
               @bind="searchText" @bind:event="oninput" />
    </div>
    <button class="btn btn-primary" @onclick="() => showCreateForm = !showCreateForm">
        @(showCreateForm ? "Cancel" : "+ New Shipment")
    </button>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">Create Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Recipient Name" @bind="newShipment.RecipientName" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
                </div>
            </div>
            <button class="btn btn-success mt-2" @onclick="CreateShipmentAsync">Create</button>
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments…</em></p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Shipped</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td><span class="badge @StatusBadge(s.Status)">@s.Status</span></td>
                        <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            <select class="form-select form-select-sm" style="width:auto;display:inline-block"
                                    value="@((int)s.Status)"
                                    @onchange="e => UpdateStatusAsync(s, e)">
                                @foreach (var st in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@((int)st)">@st</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    private List<ShipmentDto>? shipments;
    private string statusFilter = "";
    private string searchText = "";
    private bool showCreateForm;
    private ShipmentDto newShipment = new();

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? []).Where(s =>
            (string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter) &&
            (string.IsNullOrEmpty(searchText) ||
             s.TrackingNumber.Contains(searchText, StringComparison.OrdinalIgnoreCase) ||
             s.Destination.Contains(searchText, StringComparison.OrdinalIgnoreCase)));

    private async Task CreateShipmentAsync()
    {
        var created = await ShipmentService.CreateShipmentAsync(newShipment);
        shipments?.Insert(0, created);
        newShipment = new();
        showCreateForm = false;
    }

    private async Task UpdateStatusAsync(ShipmentDto shipment, ChangeEventArgs e)
    {
        var newStatus = (ShipmentStatus)int.Parse(e.Value!.ToString()!);
        await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
        shipment.Status = newStatus;
        if (newStatus == ShipmentStatus.Delivered)
            shipment.ActualDelivery = DateTime.UtcNow;
    }

    private static string StatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentStatus.Returned => "bg-danger",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-light text-dark",
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@using Microsoft.AspNetCore.Components.Authorization
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService
@inject AuthenticationStateProvider AuthStateProvider

<PageTitle>Track Shipment</PageTitle>

<h2>🔍 Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. SHP-20260701-100001)"
                   @bind="trackingInput" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchByTrackingAsync">Track</button>
        </div>
    </div>
</div>

@if (searching)
{
    <p><em>Searching…</em></p>
}
else if (trackedShipment is not null)
{
    <div class="card mb-4">
        <div class="card-header bg-dark text-white">
            <strong>@trackedShipment.TrackingNumber</strong>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <p><strong>From:</strong> @trackedShipment.Origin</p>
                    <p><strong>To:</strong> @trackedShipment.Destination</p>
                    <p><strong>Recipient:</strong> @trackedShipment.RecipientName</p>
                </div>
                <div class="col-md-6">
                    <p><strong>Status:</strong> <span class="badge @StatusBadge(trackedShipment.Status) fs-6">@trackedShipment.Status</span></p>
                    <p><strong>Shipped:</strong> @trackedShipment.ShippedDate.ToString("MMMM dd, yyyy")</p>
                    <p><strong>Estimated Delivery:</strong> @trackedShipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</p>
                    @if (trackedShipment.ActualDelivery.HasValue)
                    {
                        <p><strong>Delivered:</strong> @trackedShipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")</p>
                    }
                </div>
            </div>

            <!-- Visual progress -->
            <div class="mt-3">
                <h6>Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @ProgressBarClass(trackedShipment.Status)"
                         role="progressbar" style="width: @ProgressPercent(trackedShipment.Status)%">
                        @trackedShipment.Status
                    </div>
                </div>
            </div>
        </div>
    </div>
}
else if (searchAttempted)
{
    <div class="alert alert-warning">No shipment found with that tracking number.</div>
}

<hr />

<h4>📋 My Shipments</h4>

@if (myShipments is null)
{
    <p><em>Loading your shipments…</em></p>
}
else if (!myShipments.Any())
{
    <p class="text-muted">You have no shipments yet.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in myShipments)
                {
                    <tr style="cursor:pointer" @onclick="() => TrackExisting(s.TrackingNumber)">
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Destination</td>
                        <td><span class="badge @StatusBadge(s.Status)">@s.Status</span></td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private string trackingInput = "";
    private ShipmentDto? trackedShipment;
    private List<ShipmentDto>? myShipments;
    private bool searching;
    private bool searchAttempted;

    protected override async Task OnInitializedAsync()
    {
        var authState = await AuthStateProvider.GetAuthenticationStateAsync();
        var email = authState.User.FindFirst(System.Security.Claims.ClaimTypes.Email)?.Value
                 ?? authState.User.FindFirst("email")?.Value
                 ?? authState.User.Identity?.Name ?? "";

        if (!string.IsNullOrEmpty(email))
            myShipments = await ShipmentService.GetShipmentsForCustomerAsync(email);
        else
            myShipments = [];
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchByTrackingAsync();
    }

    private async Task SearchByTrackingAsync()
    {
        if (string.IsNullOrWhiteSpace(trackingInput)) return;
        searching = true;
        searchAttempted = true;
        trackedShipment = null;
        trackedShipment = await ShipmentService.GetByTrackingNumberAsync(trackingInput.Trim());
        searching = false;
    }

    private void TrackExisting(string trackingNumber)
    {
        trackingInput = trackingNumber;
        _ = SearchByTrackingAsync();
    }

    private static int ProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 55,
        ShipmentStatus.Returned => 100,
        _ => 0,
    };

    private static string ProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-warning",
        ShipmentStatus.Returned => "bg-danger",
        _ => "bg-primary progress-bar-striped progress-bar-animated",
    };

    private static string StatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentStatus.Returned => "bg-danger",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-light text-dark",
    };
}

